CREATE POLICY own_case_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='lexia-case-files' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY own_case_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='lexia-case-files' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY own_case_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='lexia-case-files' AND (storage.foldername(name))[1]=auth.uid()::text);